import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
D={f:pd.read_csv(f)[::5].reset_index(drop=True) for f in glob.glob('train/*.csv')+glob.glob('val/*.csv')}
def sim(p,d):
  Kp,Tw,Tp,Kq,Tq,Kv=p; dt=0.005
  th=d.bus_angle_rad.values;V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values
  P0=d.active_power_pu[0];Q0=d.reactive_power_pu[0]
  xt=th[0];w=0;pf=P0;qf=Q0;Ps=[];Qs=[]
  for k in range(len(th)):
    Ps.append(pf+Kv*0*(V[k]-V[0]));Qs.append(qf)
    w_=(th[k]-xt)/Tw  # rad/s
    xt+=dt*w_
    pf+=dt*(P0-Kp*w_/(2*np.pi*60)-pf)/Tp
    qf+=dt*(Q0+Kq*(Vs[k]-V[k])-qf)/Tq
  return np.array(Ps),np.array(Qs)
def res(p,fs):
  r=[]
  for f in fs:
    d=D[f];P,Q=sim(p,d);r+= [P-d.active_power_pu,Q-d.reactive_power_pu]
  return np.concatenate(r)
tr=[f for f in D if 'train' in f]
s=least_squares(res,[17,.05,.3,10,.2,0],args=(tr,),bounds=([0,.005,.005,0,.005,-1],[200,2,5,200,5,1]),x_scale=[10,.1,.1,10,.1,1])
print(s.x)
for f in D:
  d=D[f];P,Q=sim(s.x,d);print(f,np.sqrt(np.mean((P-d.active_power_pu)**2))/d.active_power_pu.std(),np.sqrt(np.mean((Q-d.reactive_power_pu)**2))/d.reactive_power_pu.std())

import pandas as pd,numpy as np,glob
from scipy.signal import lfilter
D={f:pd.read_csv(f)[::5].reset_index(drop=True) for f in glob.glob('train/*.csv')+glob.glob('val/*.csv')}
import pickle;pickle.dump(D,open('D.pkl','wb'))
for f in D:
  d=D[f];a=np.exp(-0.005/2)
  F=lambda x:lfilter([1-a],[1,-a],x-x[0])
  w=np.gradient(d.bus_angle_rad.values,0.005)/377
  dq=F(d.reactive_power_pu.values);X=np.c_[F(d.voltage_setpoint_pu.values-d.voltage_pu.values),F(d.active_power_pu.values),F(w)]
  c=np.linalg.lstsq(X[400:],dq[400:],rcond=None)[0];print(f,c.round(3),np.std(dq[400:]-X[400:]@c)/np.std(dq))

